/**
 * ai-overview.js — shared "Overview by AI" (#196) engine.
 *
 * A prose 1–2 page orientation, generated by running Claude AGENTICALLY over
 * CodeExam's own MCP tools: the model follows the orientation path in
 * AI_OVERVIEW_PROMPT, calling mcp__code-exam__* against the target index.
 * Non-air-gapped — shells out to the `claude` CLI with CE's own mcp-server
 * (src/mcp-server.js) pointed at an index directory.
 *
 * Shared by the GUI route (src/server.js `/api/ai-overview`) and the CLI
 * command (src/index.js `--overview-by-ai`) so the prompt + tool allow-list +
 * spawn plumbing can't drift between the two surfaces. The flow/prompt were
 * validated across six diverse indexes before this was wired.
 *
 * Deferred (#196 roadmap): small-codebase direct read, multi-provider/ensemble,
 * local-LLM (Qwen3) engine, AI↔non-AI merge.
 */

import { spawn } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url)); // src/core
const MCP_SERVER = path.join(__dirname, '..', 'mcp-server.js');  // src/mcp-server.js

// The MCP tools the model is allowed to call. Comma-joined (no spaces) so the
// value rides the shell:true command line safely. Kept deliberately tight to
// the orientation path; digest/vocabulary/models_used are skipped by the model
// itself on minified targets (see prompt step 1).
export const AI_OVERVIEW_TOOLS = [
  'overview', 'vocabulary', 'digest', 'stats', 'list_files', 'list_classes',
  'entry_points', 'hotspots', 'models_used', 'command_catalog', 'regex_search',
  'search', 'call_tree', 'struct_dupes', 'show_file', 'referenced_resources',
].map(t => `mcp__code-exam__${t}`).join(',');

export const AI_OVERVIEW_PROMPT = `You are orienting a code examiner to an unfamiliar codebase using the CodeExam MCP tools (mcp__code-exam__*) over the currently-loaded index. Produce a SHORT prose orientation — 2-4 short paragraphs (NOT one long block, NOT bullet lists), then the two labeled lists at the end. Budget: ~5-8 tool calls; do not exceed ~5 digests.

STYLE — read first:
- Write about the CODEBASE, not about CodeExam. If a CE signal is misleading, quietly reach the right answer and state it as a plain fact about the code — do NOT narrate CE's mechanics. Write "the inference engine is the downloaded llama.cpp; the top-level C++ is N-API host glue," NOT "CE's density ranking is misleading here — it's actually host glue." The reader cares about the code they're about to examine, not how the overview corrects CE's low-level signals.
- Vary your wording; don't lean on stock phrases or a fixed template. Reach for a framing (e.g. "a layer over two systems", "host vs vendored", "the spine"/"center of gravity") ONLY when this codebase genuinely fits it — never force it onto every index.
- Be terse on trouble: if a tool errors, the index is empty/minified/unreachable, or something is a CE indexing artifact, note it in ONE sentence and move on. NEVER write a troubleshooting log, ask the reader a question, or leak your own process ("I now have a complete picture…"). If you truly cannot orient (no tools reachable / empty index), output a single line saying so and stop.
- Output ONLY the overview; no preamble.

1. DETECT THE TARGET'S SHAPE FIRST — call overview, then stats. Then choose a path:
   - Minified/bundled or binary-dominated (minified module names, .node/binary symbols like napi_*, huge per-file function counts): lead with command_catalog and regex_search on distinctive strings; do NOT call digest/vocabulary/models_used (they fail on minified code).
   - A collection (CE flags >=2 substantial top-level folders): say so in one sentence, then orient PER-REPO with list_files <repo>/. Don't belabor that it isn't one project — and sanity-check the flag, since a high line count dominated by data/logs/markdown is not a multi-repo collection.
   - Readable single project: overview -> vocabulary -> digest the top 3-5 key files (stop at ~5) -> models_used. command_catalog for a CLI/route app; regex_search for internal protocols/routes (e.g. /api/ or other prefixes you observe); call_tree from an entry point for control flow. referenced_resources for the external surface (env vars, hosts/URLs, embedded SQL, external commands, data/config files); if one data/config file dominates by reference count, name it (use the counts, don't assume).
   - Read the README/conventions for product framing if present (show_file on README*, CLAUDE.md, AGENTS.md).

2. When there IS vendored/bundled dependency code, separate it from the host app — density-ranked signals point at the biggest dependency, not the host. Skip this entirely if nothing is vendored.

3. Recognize CE's own artifacts SILENTLY (.op = CE binary-string captures, zip!-prefixed paths = archive members, single-letter names = expected in minified bundles). They're not findings — don't explain them to the reader unless one is genuinely load-bearing.

4. Include ONE AI/ML sentence from models_used: detected (name them, api vs local — but at most a couple, and flag obviously-example IDs as examples; don't enumerate a suspect list), none detected, or inconclusive (minified / var-held). Distrust models_used counts on minified code.

5. Treat naming/comments/docs as indicia, not ground truth — they drift and are often stale on active code. When a specific claim rests on a doc/name the code doesn't confirm, flag it briefly in passing; don't turn this into a ritual or a labeled two-column checklist.

6. Prefer evidence over speculation: instead of "almost certainly X — confirm with tool Y," just run Y within budget. Resolve anything you raise in the same breath, or drop it (no teasers). Use the signals CE computes across the whole corpus — clones (struct_dupes), structural centrality (hotspots), IDF vocabulary, the external surface, what-was-skipped — to say something a quick skim wouldn't, but keep it about the code.

OUTPUT (prose + two short labeled lists):
- The 2-4 short paragraphs (what it is, architecture, what it does, the AI/ML sentence).
- "Where to look first / highest-payback CE commands" — each with one-line reasoning, including "skip X here" when a tool is defeated by the target.
- "Questions to start with" — each paired with the single CE command that most DIRECTLY answers it (verify a structural claim with the confirming command — a clone claim uses struct_dupes --cross-source-only or list_files, not a bare struct_dupes). Directed exploration, not noodling.
Emit file/function references as backticked paths (\`path\` or \`path@func\`) so they can be made clickable.`;

// Grounding mode (#196, mirrors the chat's #36 clauses): how freely the overview
// may use knowledge beyond the indexed codebase. Default 'grounded' — forensic by
// default. (Chat keeps its own copy in server.js; a later cleanup can dedupe both
// into one shared module.)
export const AI_OVERVIEW_GROUNDING_CLAUSES = {
  grounded: `GROUNDING — STRICT: Base the overview ONLY on what the tools surface about this code. If something cannot be determined from the code, say so rather than filling the gap with general knowledge. Do NOT assert the purpose of a referenced library/algorithm, the research domain, or any external framing as fact about this codebase unless the code itself states it.`,
  augmented: `GROUNDING — AUGMENTED: You may combine what the tools surface with your general knowledge for the richest orientation — naming the domain or research area, explaining what a referenced library or algorithm does, and supplying standard context the code assumes its readers already know.`,
  attributed: `GROUNDING — ATTRIBUTED: Combine codebase evidence with general knowledge, but make provenance explicit — distinguish claims grounded in THIS code (cite the file/function/tool) from claims that come from your general knowledge or inference. Flag every non-trivial external claim as such.`,
};

// AI_OVERVIEW_PROMPT + the selected grounding clause (default grounded).
export function aiOverviewPrompt(grounding) {
  const clause = AI_OVERVIEW_GROUNDING_CLAUSES[grounding] || AI_OVERVIEW_GROUNDING_CLAUSES.grounded;
  return `${AI_OVERVIEW_PROMPT}\n\n${clause}`;
}

/**
 * Run "Overview by AI" against an index directory. Resolves with the prose
 * string (claude exit 0 + non-empty stdout) or rejects with an Error whose
 * message is safe to surface to the user.
 *
 * @param {object} opts
 * @param {string} opts.indexPath   Index directory to point the MCP server at (required).
 * @param {string} [opts.model]     Claude model id (e.g. claude-sonnet-4-6); omitted → CLI default.
 * @param {number} [opts.timeoutMs] Hard wall-clock limit (default 600000 = 10 min).
 * @param {(line:string)=>void} [opts.onStderr] Optional live stderr sink (CLI progress).
 * @returns {Promise<string>}
 */
export function runAiOverview({ indexPath, model, timeoutMs = 600000, grounding, onStderr } = {}) {
  return new Promise((resolve, reject) => {
    if (!indexPath) return reject(new Error('runAiOverview: indexPath is required.'));

    let tmpDir;
    try {
      // Neutral temp cwd → no CLAUDE.md autodiscovery for the spawned agent.
      tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ce-ai-ov-'));
      const cfg = { mcpServers: { 'code-exam': { command: 'node', args: [MCP_SERVER, '--index-path', path.resolve(indexPath)] } } };
      fs.writeFileSync(path.join(tmpDir, 'mcp.json'), JSON.stringify(cfg));
    } catch (e) {
      return reject(new Error(`AI Overview setup failed: ${e.message}`));
    }

    let done = false;
    const cleanup = () => { try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ } };
    const finish = (fn, arg) => { if (done) return; done = true; cleanup(); fn(arg); };

    // Space-containing values stay off the (shell:true) command line: prompt via
    // stdin, mcp-config via a quoted file path, tools comma-separated.
    const args = ['-p', '--output-format', 'text',
      '--mcp-config', `"${path.join(tmpDir, 'mcp.json')}"`,
      '--allowedTools', AI_OVERVIEW_TOOLS,
      '--permission-mode', 'bypassPermissions'];
    if (model) args.push('--model', model);

    let child;
    try {
      child = spawn('claude', args, {
        cwd: tmpDir, shell: true, windowsHide: true,
        // Large indexes (e.g. .spinellis, ~6.8M lines) load synchronously in the
        // MCP server's startup (mcp-server.js main() loads the index before
        // server.connect()), so the default ~30s MCP startup timeout drops the
        // server before its tools register — Claude then reports "tools not
        // reachable". Raise MCP_TIMEOUT (ms) above this run's timeout so a slow
        // load still handshakes and any genuine failure surfaces as the clean
        // timeout below. (A handshake-first lazy-load in mcp-server.js is the
        // more robust follow-up.)
        env: { ...process.env, MCP_TIMEOUT: String(timeoutMs + 60000) },
      });
    } catch (e) {
      return finish(reject, new Error(`Could not launch the 'claude' CLI (AI Overview is non-air-gapped and needs it): ${e.message}`));
    }

    let out = '', err = '';
    child.stdout.on('data', (d) => { out += d; });
    child.stderr.on('data', (d) => { err += d; if (onStderr) onStderr(String(d)); });
    child.on('error', (e) => finish(reject, new Error(e.code === 'ENOENT'
      ? `The 'claude' CLI was not found on PATH. AI Overview is non-air-gapped and requires it.`
      : `AI Overview failed to launch: ${e.message}`)));
    const timer = setTimeout(() => {
      try { child.kill(); } catch { /* */ }
      finish(reject, new Error(`AI Overview timed out (${Math.round(timeoutMs / 60000)} min). Very large indexes (e.g. .spinellis) may need a longer --timeout.`));
    }, timeoutMs);
    child.on('close', (codeNum) => {
      clearTimeout(timer);
      if (codeNum === 0 && out.trim()) finish(resolve, out.trim());
      else finish(reject, new Error(`AI Overview failed (claude exit ${codeNum}). ${(err || '').slice(0, 400)}`.trim()));
    });
    child.stdin.write(aiOverviewPrompt(grounding));
    child.stdin.end();
  });
}
